    /**
     * Serialize {@code that} as a JSON node.
     *
     * <p>A JSON-able value is almost a JSON node as it comes, but not quite: its type rules out
     * neither a missing node, a non-finite number nor an integer outside the safe integer range
     * [-2^53 + 1, 2^53 - 1]. Each is refused here, at any depth. A null node is written as a JSON
     * null.
     *
     * <p>The result is a deep copy, and never {@code that} itself, so that the serialized document
     * does not share a tree with the instance it came from.
     *
     * @param that to be serialized
     * @return {@code that}, as a node of a JSON document
     */
    private static JsonNode jsonValueToJsonNode(JsonNode that) {
      if (that == null || that.isMissingNode()) {
        throw new _SerializeFailure(
            new Reporting.Error("Expected a JSON-able value, but got: " + that));
      }

      if (that.isNull()) {
        return JsonNodeFactory.instance.nullNode();
      }

      if (that.isNumber()) {
        final String cause = Verification.checkJsonAbleNumber(that);
        if (cause != null) {
          throw new _SerializeFailure(new Reporting.Error(cause));
        }
        return that.deepCopy();
      }

      if (that.isBoolean() || that.isTextual()) {
        return that.deepCopy();
      }

      if (that.isArray()) {
        final ArrayNode result = JsonNodeFactory.instance.arrayNode();
        int index = 0;
        for (JsonNode item : that) {
          try {
            result.add(jsonValueToJsonNode(item));
          } catch (_SerializeFailure failure) {
            failure.getError().prependSegment(new Reporting.IndexSegment(index));
            throw failure;
          }
          index++;
        }
        return result;
      }

      if (that.isObject()) {
        final ObjectNode result = JsonNodeFactory.instance.objectNode();
        final Iterator<String> names = that.fieldNames();
        while (names.hasNext()) {
          final String name = names.next();
          try {
            result.set(name, jsonValueToJsonNode(that.get(name)));
          } catch (_SerializeFailure failure) {
            failure.getError().prependSegment(new Reporting.KeySegment(name));
            throw failure;
          }
        }
        return result;
      }

      throw new _SerializeFailure(
          new Reporting.Error(
              "Expected a JSON-able value (a null, a boolean, a number, a string, "
                  + "an array or an object), but got: "
                  + that.getNodeType()));
    }

